from pathlib import Path

ROOT = Path.cwd()
OUT = ROOT / "ledgers/M3/scripts/M3-d-r9/out"
R = "ledgers/M3/scripts/M3-d-r9/out/"

mutants = []
for line in (OUT / "mutate_M3_seeds0-9_r9.out").read_text(encoding="utf-8").splitlines():
    m = re.match(r"^(KILLED|SURVIVED) (\S+?): (.*) -> (.*)$", line)
    if not m:
        continue
    status, name, description, killer = m.groups()
    mutants.append({"id": name, "description": description, "killed_by": killer if status == "KILLED" else ""})

def row(rid, check, location, status, evidence, fix=""):
    return {"id": rid, "check": check, "location": location, "status": status, "evidence": evidence, "fix": fix}

